345-void
346-Coin::after_editor_set()
347-{
348-  MovingSprite::after_editor_set();
349-
350-  if (get_walker() && get_path()->is_valid()) {
351-    if (!m_add_path) {
352-      get_path()->m_nodes.clear();
353-    }
354-  } else {
355-    if (m_add_path) {
356-      init_path_pos(m_col.m_bbox.p1());
357-    }
358-  }
359-}
