HitResponse
Rock::collision(MovingObject& other, const CollisionHit& hit)
{
  auto heavy_coin = dynamic_cast<HeavyCoin*> (&other);
  if (heavy_coin) {
    return ABORT_MOVE;
  }

  auto explosion = dynamic_cast<Explosion*> (&other);
  if (explosion) {
    return ABORT_MOVE;
  }
  Rock::update(dt_sec);
}

HitResponse
Trampoline::collision(MovingObject& other, const CollisionHit& hit)
{
  auto heavy_coin = dynamic_cast<HeavyCoin*> (&other);
  if (heavy_coin) {
    return ABORT_MOVE;
  }
  auto player = dynamic_cast<Player*> (&other);
  //Trampoline works for player
  if (player && !is_grabbed())
  {
    player->override_velocity();
    if (player->m_does_buttjump)
      {
        return FORCE_MOVE;
      }
    }
  }

  const auto* heavy_coin = dynamic_cast<HeavyCoin*>(&other);
  if (heavy_coin)
  {
    return ABORT_MOVE;
  }

  return FORCE_MOVE;
  if (m_is_glinting && m_can_glint && !m_holds_coins)
  {
    const int num_coins = get_coins_worth();

    for (int i = 0; i < num_coins; ++i)
    {
      const float coin_x = get_bbox().get_middle().x - 16.0f;
      const float coin_y = get_bbox().get_top() - 32.0f;

      Sector::get().add<HeavyCoin>(Vector(coin_x, coin_y),
                                   Vector(graphicsRandom.randf(-96.0f, 96.0f),
                                   0.0f));
    }
  }

  if (m_parent_dispenser != nullptr)
  vx = vector.x;
  vy = vector.y;
}

void
Physic::set_acceleration(const Vector& vector)
{
  ax = vector.x;
  ay = vector.y;
}

Vector
Physic::get_movement(float dt_sec)
{
  float grav = gravity_enabled_flag ? (Sector::get().get_gravity() * gravity_modifier * 100.0f) : 0;

  // Semi-implicit Euler integration
  // with constant acceleration, this will result in a position delta of
  // v t + .5 a t (t+dt_sec) at total time t
  vx += ax * dt_sec;
  vy += (ay + grav) * dt_sec;
  Vector result(vx * dt_sec, vy * dt_sec);

  return result;
}

